function isMirrorSequence(arr) {
  const n = arr.length;
  for (let i = 0; i < Math.floor(n / 2); i++) {
    if (arr[i] !== arr[n - 1 - i]) return false;
  }
  return true;
}

// Example executions:
console.log('Test 1 [1, 2, 3, 3, 2, 1]:', isMirrorSequence([1, 2, 3, 3, 2, 1]));
console.log('Test 2 [7, 8, 9, 8, 7]:', isMirrorSequence([7, 8, 9, 8, 7]));

function lengthOfLongestSubstring(s) {
  const seen = new Map();
  let left = 0;
  let maxLength = 0;

  for (let right = 0; right < s.length; right++) {
    const char = s[right];
    if (seen.has(char) && seen.get(char) >= left) {
      left = seen.get(char) + 1;
    }
    seen.set(char, right);
    maxLength = Math.max(maxLength, right - left + 1);
  }

  return maxLength;
}

// Example executions:
console.log('Example 1 ("abcabcbb"):', lengthOfLongestSubstring("abcabcbb")); // 3
console.log('Example 2 ("bbbbb"):', lengthOfLongestSubstring("bbbbb"));       // 1
console.log('Example 3 ("pwwkew"):', lengthOfLongestSubstring("pwwkew"));     // 3

function minSubarrayRemoval(nums) {
  const n = nums.length;
  let right = n - 1;
  const rightSet = new Set();
  while (right >= 0 && !rightSet.has(nums[right])) {
    rightSet.add(nums[right]);
    right--;
  }
  right++;
  if (right === 0) return 0;

  let minRemoval = right;
  const leftSet = new Set();
  for (let left = 0; left < n; left++) {
    if (leftSet.has(nums[left])) break;
    leftSet.add(nums[left]);
    while (right < n && rightSet.has(nums[left])) {
      rightSet.delete(nums[right]);
      right++;
    }
    minRemoval = Math.min(minRemoval, Math.max(0, right - left - 1));
  }
  return minRemoval;
}

// Example executions:
console.log('Example 1 [1, 2, 3, 4]:', minSubarrayRemoval([1, 2, 3, 4]));
console.log('Example 2 [1, 2, 1, 2, 3]:', minSubarrayRemoval([1, 2, 1, 2, 3]));
console.log('Example 3 [2, 2, 2]:', minSubarrayRemoval([2, 2, 2]));

function closestPairDifference(numbers, target) {
  const nums = [...numbers].sort((a, b) => a - b);
  let left = 0, right = nums.length - 1;
  let minDiff = Infinity;

  while (left < right) {
    const sum = nums[left] + nums[right];
    const diff = Math.abs(sum - target);
    minDiff = Math.min(minDiff, diff);
    if (sum < target) left++;
    else if (sum > target) right--;
    else return 0;
  }
  return minDiff;
}

// Example executions:
console.log('Example 1 ([1, 3, 8, 10], 12):', closestPairDifference([1, 3, 8, 10], 12));
console.log('Example 2 ([5, 2, 7, 4], 10):', closestPairDifference([5, 2, 7, 4], 10));
